//! Oracle tests generated by `target/canon/dbghelp/gen.py`. Do not edit.
//!
//! Each row is one input that the verbatim functions in Wine's `dlls/dbghelp/dwarf.c`
//! at commit `e2aa6cd75ae60acd90ff384feee171ce994f0f6d` decode with no ASan or UBSan
//! report. The initial-length rows place their input at offset 4 of an 8-byte
//! aligned buffer, so the 8-byte read is aligned.
//!
//! Sanitizer-flagged vectors, excluded from the rows:
//! - uleb 8080808080808080808000: flagged: dwarf_verbatim.inc:43:39: runtime error: shift exponent 70 is too large for 64-bit type 'long unsigned int'
//! - sleb 8080808080808080808000: flagged: dwarf_verbatim.inc:60:39: runtime error: shift exponent 70 is too large for 64-bit type 'long unsigned int'
//! - initlen_base0 ffffffff2a00000000000000: flagged: dwarf_verbatim.inc:25:12: runtime error: load of misaligned address 0x... for type 'const UINT64', which requires 8 byte alignment

use super::*;

const ULEB128_ROWS: &[(&str, u64, usize)] = &[
    ("00", 0, 1),
    ("8001", 128, 2),
    ("e58e26", 624485, 3),
    ("8080808010", 4294967296, 5),
    ("ffffffffffffffffff01", 18446744073709551615, 10),
];

const SLEB128_ROWS: &[(&str, i64, usize)] = &[
    ("02", 2, 1),
    ("7e", -2, 1),
    ("807f", -128, 2),
    ("c0bb78", -123456, 3),
    ("8080808080808080807f", -9223372036854775808, 10),
    ("ffffffffffffffffff7f", -1, 10),
];

const LEB128_LEN_ROWS: &[(&str, usize)] = &[("02", 1), ("ffffffffffffffffff01", 10)];

const ADDR_ROWS: &[(u8, &str, u64)] = &[
    (4, "78563412", 0x12345678),
    (4, "ffffffff", 0xffffffff),
    (8, "efcdab8967452301", 0x123456789abcdef),
    (8, "ffffffffffffffff", 0xffffffffffffffff),
];

const INITIAL_LENGTH_ROWS: &[(&str, u64, u8, usize)] = &[
    ("2a000000", 0x2a, 4, 4),
    ("f0ffffff", 0xfffffff0, 4, 4),
    ("ffffffff2a00000000000000", 0x2a, 8, 12),
    ("ffffffff0807060504030201", 0x102030405060708, 8, 12),
];

fn hex_bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

#[test]
fn read_uleb128_matches_wine_oracle() {
    for &(hex, value, consumed) in ULEB128_ROWS {
        assert_eq!(
            read_uleb128(&hex_bytes(hex)),
            Some((value, consumed)),
            "uleb128 {hex}"
        );
    }
}

#[test]
fn read_sleb128_matches_wine_oracle() {
    for &(hex, value, consumed) in SLEB128_ROWS {
        assert_eq!(
            read_sleb128(&hex_bytes(hex)),
            Some((value, consumed)),
            "sleb128 {hex}"
        );
    }
}

#[test]
fn leb128_len_matches_wine_oracle() {
    for &(hex, len) in LEB128_LEN_ROWS {
        assert_eq!(
            leb128_len(&hex_bytes(hex)),
            Some(len),
            "leb128 length {hex}"
        );
    }
}

#[test]
fn read_addr_matches_wine_oracle() {
    for &(word_size, hex, value) in ADDR_ROWS {
        assert_eq!(
            read_addr(&hex_bytes(hex), word_size),
            Some(value),
            "addr {word_size} {hex}"
        );
    }
}

#[test]
fn read_initial_length_matches_wine_oracle() {
    for &(hex, value, offset_size, consumed) in INITIAL_LENGTH_ROWS {
        let expected = InitialLength {
            value,
            offset_size,
            consumed,
        };
        assert_eq!(
            read_initial_length(&hex_bytes(hex)),
            Some(expected),
            "initial length {hex}"
        );
    }
}
